CREATE TABLE PS_GameDefs_MapProperties (
    MapID INTEGER PRIMARY KEY CHECK (MapID BETWEEN 0 AND 65535),
    MapType TEXT NOT NULL DEFAULT '',
    WarType TEXT NOT NULL DEFAULT '',
    CreateType TEXT NOT NULL DEFAULT '',
    MinLevel INTEGER NOT NULL DEFAULT 0 CHECK (MinLevel BETWEEN 0 AND 65535),
    MaxLevel INTEGER NOT NULL DEFAULT 0 CHECK (MaxLevel BETWEEN 0 AND 65535),
    CreateMinUser INTEGER NOT NULL DEFAULT 0 CHECK (CreateMinUser BETWEEN 0 AND 65535),
    EnterMaxUser INTEGER NOT NULL DEFAULT 30 CHECK (EnterMaxUser BETWEEN 0 AND 65535),
    ExpireMinutes INTEGER NOT NULL DEFAULT 0 CHECK (ExpireMinutes BETWEEN 0 AND 65535),
    WeatherType INTEGER NOT NULL DEFAULT 0 CHECK (WeatherType BETWEEN 0 AND 2),
    WeatherFrequency INTEGER NOT NULL DEFAULT 0 CHECK (WeatherFrequency BETWEEN 0 AND 65535),
    MapCurse1 INTEGER NOT NULL DEFAULT 0 CHECK (MapCurse1 BETWEEN 0 AND 65535),
    MapCurse2 INTEGER NOT NULL DEFAULT 0 CHECK (MapCurse2 BETWEEN 0 AND 65535),
    MapCurse3 INTEGER NOT NULL DEFAULT 0 CHECK (MapCurse3 BETWEEN 0 AND 65535),
    MapModifier1 INTEGER NOT NULL DEFAULT 0 CHECK (MapModifier1 BETWEEN 0 AND 2147483647),
    MapModifier2 INTEGER NOT NULL DEFAULT 0 CHECK (MapModifier2 BETWEEN 0 AND 2147483647),
    MapModifier3 INTEGER NOT NULL DEFAULT 0 CHECK (MapModifier3 BETWEEN 0 AND 2147483647),
    LightRebirthMapID INTEGER CHECK (LightRebirthMapID BETWEEN 0 AND 65535),
    LightRebirthX REAL,
    LightRebirthY REAL,
    LightRebirthZ REAL,
    FuryRebirthMapID INTEGER CHECK (FuryRebirthMapID BETWEEN 0 AND 65535),
    FuryRebirthX REAL,
    FuryRebirthY REAL,
    FuryRebirthZ REAL,
    Schedule1Day INTEGER CHECK (Schedule1Day BETWEEN 0 AND 7),
    Schedule1StartHour INTEGER CHECK (Schedule1StartHour BETWEEN 0 AND 23),
    Schedule1DurationHours INTEGER CHECK (Schedule1DurationHours BETWEEN 0 AND 65535),
    Schedule2Day INTEGER CHECK (Schedule2Day BETWEEN 0 AND 7),
    Schedule2StartHour INTEGER CHECK (Schedule2StartHour BETWEEN 0 AND 23),
    Schedule2DurationHours INTEGER CHECK (Schedule2DurationHours BETWEEN 0 AND 65535),
    Schedule3Day INTEGER CHECK (Schedule3Day BETWEEN 0 AND 7),
    Schedule3StartHour INTEGER CHECK (Schedule3StartHour BETWEEN 0 AND 23),
    Schedule3DurationHours INTEGER CHECK (Schedule3DurationHours BETWEEN 0 AND 65535),
    Schedule4Day INTEGER CHECK (Schedule4Day BETWEEN 0 AND 7),
    Schedule4StartHour INTEGER CHECK (Schedule4StartHour BETWEEN 0 AND 23),
    Schedule4DurationHours INTEGER CHECK (Schedule4DurationHours BETWEEN 0 AND 65535),
    Schedule5Day INTEGER CHECK (Schedule5Day BETWEEN 0 AND 7),
    Schedule5StartHour INTEGER CHECK (Schedule5StartHour BETWEEN 0 AND 23),
    Schedule5DurationHours INTEGER CHECK (Schedule5DurationHours BETWEEN 0 AND 65535),
    Schedule6Day INTEGER CHECK (Schedule6Day BETWEEN 0 AND 7),
    Schedule6StartHour INTEGER CHECK (Schedule6StartHour BETWEEN 0 AND 23),
    Schedule6DurationHours INTEGER CHECK (Schedule6DurationHours BETWEEN 0 AND 65535),
    Schedule7Day INTEGER CHECK (Schedule7Day BETWEEN 0 AND 7),
    Schedule7StartHour INTEGER CHECK (Schedule7StartHour BETWEEN 0 AND 23),
    Schedule7DurationHours INTEGER CHECK (Schedule7DurationHours BETWEEN 0 AND 65535),
    CHECK (MaxLevel = 0 OR MinLevel <= MaxLevel),
    CHECK ((LightRebirthMapID IS NULL AND LightRebirthX IS NULL AND LightRebirthY IS NULL AND LightRebirthZ IS NULL) OR (LightRebirthMapID IS NOT NULL AND LightRebirthX IS NOT NULL AND LightRebirthY IS NOT NULL AND LightRebirthZ IS NOT NULL)),
    CHECK ((FuryRebirthMapID IS NULL AND FuryRebirthX IS NULL AND FuryRebirthY IS NULL AND FuryRebirthZ IS NULL) OR (FuryRebirthMapID IS NOT NULL AND FuryRebirthX IS NOT NULL AND FuryRebirthY IS NOT NULL AND FuryRebirthZ IS NOT NULL)),
    CHECK ((Schedule1Day IS NULL AND Schedule1StartHour IS NULL AND Schedule1DurationHours IS NULL) OR (Schedule1Day IS NOT NULL AND Schedule1StartHour IS NOT NULL AND Schedule1DurationHours IS NOT NULL)),
    CHECK ((Schedule2Day IS NULL AND Schedule2StartHour IS NULL AND Schedule2DurationHours IS NULL) OR (Schedule2Day IS NOT NULL AND Schedule2StartHour IS NOT NULL AND Schedule2DurationHours IS NOT NULL)),
    CHECK ((Schedule3Day IS NULL AND Schedule3StartHour IS NULL AND Schedule3DurationHours IS NULL) OR (Schedule3Day IS NOT NULL AND Schedule3StartHour IS NOT NULL AND Schedule3DurationHours IS NOT NULL)),
    CHECK ((Schedule4Day IS NULL AND Schedule4StartHour IS NULL AND Schedule4DurationHours IS NULL) OR (Schedule4Day IS NOT NULL AND Schedule4StartHour IS NOT NULL AND Schedule4DurationHours IS NOT NULL)),
    CHECK ((Schedule5Day IS NULL AND Schedule5StartHour IS NULL AND Schedule5DurationHours IS NULL) OR (Schedule5Day IS NOT NULL AND Schedule5StartHour IS NOT NULL AND Schedule5DurationHours IS NOT NULL)),
    CHECK ((Schedule6Day IS NULL AND Schedule6StartHour IS NULL AND Schedule6DurationHours IS NULL) OR (Schedule6Day IS NOT NULL AND Schedule6StartHour IS NOT NULL AND Schedule6DurationHours IS NOT NULL)),
    CHECK ((Schedule7Day IS NULL AND Schedule7StartHour IS NULL AND Schedule7DurationHours IS NULL) OR (Schedule7Day IS NOT NULL AND Schedule7StartHour IS NOT NULL AND Schedule7DurationHours IS NOT NULL))
) STRICT;

CREATE TABLE PS_GameDefs_CharacterStartPositions (
    Race INTEGER PRIMARY KEY CHECK (Race BETWEEN 0 AND 3),
    MapID INTEGER NOT NULL CHECK (MapID BETWEEN 0 AND 65535),
    X REAL NOT NULL,
    Y REAL NOT NULL,
    Z REAL NOT NULL
) STRICT;


